  return getData(request.get(`/user/info/${id}`));
}

export function apiAdminUserMoney(
  id: number,
  money: string,
  type: "add" | "sub",
): Promise<{ balance: string }> {
  return getData(request.post(`/user/update_other/${id}`, {
    status: type === "add" ? 1 : 2,
    number: money,
    type: 1,
  }, {
    headers: { "Idempotency-Key": crypto.randomUUID() },
  }));
}

